style.css:
@-moz-document domain("character.ai") {
body {
        background-color: #121212; /* Fond noir */
        color: #ffffff; /* Texte blanc */
    }

    .message {
        background-color: #1e1e1e; /* Fond des messages */
        border: 1px solid #444444; /* Bordure des messages */
        color: #ffffff; /* Couleur du texte des messages */
        padding: 10px; /* Ajoute un peu d'espace autour du texte */
        border-radius: 5px; /* Arrondit les bords des messages */
    }

    .message:hover {
        background-color: #333333; /* Fond plus clair au survol */
    }

    a {
        color: #bb86fc; /* Couleur des liens */
    }

    /* Supprimer les pointillés autour des messages modifiés */
    .edited {
        outline: none;
    }
}
